<div id="wrapper"><div class="content sccc-app"><div class="sccc-page-head"><div><h3><?= _l('sccc_reports') ?></h3><p class="text-muted"><?= _l('sccc_reports_subtitle') ?></p></div></div><?php $disp=$this->db->select('COALESCE(disposition,"unassigned") d,COUNT(*) c')->group_by('disposition')->get(db_prefix().'sccc_calls')->result_array();?><div class="row"><div class="col-md-6"><div class="sccc-card"><h4><?= _l('sccc_call_outcomes')?></h4><canvas id="scccOutcomeChart" height="240"></canvas></div></div><div class="col-md-6"><div class="sccc-card"><h4><?= _l('sccc_disposition_report')?></h4><table class="table"><thead><tr><th><?= _l('sccc_disposition')?></th><th><?= _l('sccc_total')?></th></tr></thead><tbody><?php foreach($disp as $d){?><tr><td><?= html_escape($d['d'])?></td><td><?= (int)$d['c']?></td></tr><?php }?></tbody></table></div></div></div><script>window.scccOutcome=<?= json_encode($disp) ?>;</script></div></div><?php init_tail(); ?>